from typing import Annotated, Literal, Optional
from langchain_core.messages import BaseMessage
from langgraph.graph.message import add_messages
from pydantic import BaseModel, Field
from typing_extensions import TypedDict

ModerationStateStatus = Literal[
    "pending_ai",
    "approved",
    "crisis_held",
    "rejected",
]


class TriageResult(BaseModel):
    """Structured assessment output generated by the safety triage agent."""

    severity: int = Field(
        ge=0,
        le=10,
        description="Calculated risk severity score ranging from 0 to 10",
    )
    roast_allowed: bool = Field(
        description="Whether the confession is deemed safe and suitable for satirical roast",
    )
    reason: str = Field(
        description="Concise justification detailing the reasoning behind the triage classification",
    )


class ConfessionState(TypedDict, total=False):
    """Complete conversational and processing state of a confession throughout the graph."""

    confession_id: int | str
    content: str
    mod_status: ModerationStateStatus
    severity: int
    roast_allowed: bool
    triage_reason: str
    ai_roast: Optional[str]
    ai_defense: Optional[str]
    ai_prosecution: Optional[str]
    active_powers: list[str]
    guardrails_triggered: list[str]
    messages: Annotated[list[BaseMessage], add_messages]


__all__ = [
    "ModerationStateStatus",
    "TriageResult",
    "ConfessionState",
]
